const fs = require('fs');
const path = '/data/replyCount.json';
let data = { count: 0 };
try {
  data = JSON.parse(fs.readFileSync(path, 'utf8'));
} catch (e) {}
const target = (typeof data.target === 'number' && data.target > 0) ? data.target : 50;
if (data.count >= target) { return []; }
return [{ json: { count: data.count } }];

const fs = require('fs');
let c = {};
try { c = JSON.parse(fs.readFileSync('/data/config.json', 'utf8')); } catch (e) {}
const xUser = (c && c.X_USER) ? String(c.X_USER).trim() : '';
const xPassword = (c && c.X_PASSWORD) ? String(c.X_PASSWORD) : '';
if (!xUser || !xPassword) throw new Error('X_USER and X_PASSWORD required in /data/config.json for login. Add: "X_USER": "your_email_or_handle", "X_PASSWORD": "your_password_or_app_password". See docs/setup.md');
return [{ json: { xUser, xPassword } }];

const { xUser, xPassword } = $input.first().json;
if (!xUser || !xPassword) throw new Error('xUser and xPassword required from Load config');
await $page.goto('https://twitter.com/i/flow/login', { waitUntil: 'networkidle2', timeout: 30000 });
await $page.waitForSelector('input[autocomplete="username"]', { visible: true, timeout: 15000 });
await $page.type('input[autocomplete="username"]', xUser, { delay: 50 });
await $page.evaluate(() => { const b = [...document.querySelectorAll('button[role="button"]')].find(el => /Next/i.test(el.innerText)); if (b) b.click(); });
await new Promise(r => setTimeout(r, 2500));
await $page.waitForSelector('input[name="password"], input[type="password"]', { visible: true, timeout: 15000 });
await $page.type('input[name="password"], input[type="password"]', xPassword, { delay: 50 });
await $page.evaluate(() => { const b = [...document.querySelectorAll('button[role="button"]')].find(el => /Log in/i.test(el.innerText)); if (b) b.click(); });
await $page.waitForNavigation({ waitUntil: 'networkidle0', timeout: 60000 });
const cookies = await $page.cookies();
return [{ json: { cookies } }];

const { cookies } = $input.first().json;
await $page.setCookie(...cookies);
await $page.goto('https://twitter.com/home', { waitUntil: 'networkidle2' });
await $page.waitForSelector('article[data-testid="tweet"]', { timeout: 15000 });
for (let i = 0; i < 4; i++) {
  await $page.evaluate(() => window.scrollBy(0, 800));
  await new Promise(r => setTimeout(r, 1500));
}
const tweets = await $page.$$eval('article[data-testid="tweet"]', (arts) =>
  arts.map((a) => {
    const text = a.querySelector('div[data-testid="tweetText"]')?.innerText || '';
    const link = a.querySelector('a[href*="/status/"]')?.href || '';
    const id = (link.match(/status\/(\d+)/) || [])[1];
    return { text, url: link, id };
  })
);
return tweets.slice(0, 50).filter((t) => t.id).map((t) => ({ json: { ...t, cookies } }));

const fs = require('fs');
let repliedIds = [];
try {
  repliedIds = JSON.parse(fs.readFileSync('/data/repliedIds.json', 'utf8'));
} catch (e) {}
const set = new Set(repliedIds);
return $input.all().filter((i) => !set.has(i.json.id)).map((i) => ({ json: i.json }));

const fs = require('fs');
const https = require('https');
let key = '';
try {
  const c = JSON.parse(fs.readFileSync('/data/config.json', 'utf8'));
  key = (c && c.GROQ_API_KEY) ? String(c.GROQ_API_KEY) : '';
} catch (e) {}
if (!key) throw new Error('GROQ_API_KEY missing. Create /data/config.json with {"GROQ_API_KEY":"gsk_..."}. See docs/setup.md');
const tweets = $input.all().map((i) => i.json);
if (tweets.length === 0) return [];
const prompt = 'Classify which tweets are about AI, ML, or related tech news. Reply ONLY with a JSON array of 0-based indices. No other text.\n\n' +
  tweets.map((t, i) => i + ': ' + (t.text || '').replace(/\n/g, ' ')).join('\n');
const postData = JSON.stringify({
  model: 'llama-3.1-8b-instant',
  max_tokens: 300,
  temperature: 0,
  messages: [{ role: 'user', content: prompt }]
});
const data = await new Promise((resolve, reject) => {
  const req = https.request({
    hostname: 'api.groq.com',
    path: '/openai/v1/chat/completions',
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + key,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => { body += chunk; });
    res.on('end', () => {
      try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
    });
  });
  req.on('error', reject);
  req.write(postData);
  req.end();
});
const raw = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '[]';
let indices = [];
try { indices = JSON.parse(raw); } catch (e) {}
if (!Array.isArray(indices)) indices = [];
return tweets.filter((_, i) => indices.includes(i)).map((t) => ({ json: t }));

const fs = require('fs');
const https = require('https');
let key = '';
try {
  const c = JSON.parse(fs.readFileSync('/data/config.json', 'utf8'));
  key = (c && c.GROQ_API_KEY) ? String(c.GROQ_API_KEY) : '';
} catch (e) {}
if (!key) throw new Error('GROQ_API_KEY missing. Create /data/config.json with {"GROQ_API_KEY":"gsk_..."}. See docs/setup.md');
const sys = 'You write short, natural, helpful replies to tweets. Maximum 270 characters. No spam, no unsolicited links. Be conversational and relevant.';
const items = $input.all();
for (const it of items) {
  const postData = JSON.stringify({
    model: 'llama-3.1-8b-instant',
    max_tokens: 300,
    temperature: 0,
    messages: [
      { role: 'system', content: sys },
      { role: 'user', content: 'Tweet: ' + (it.json.text || '') + '\n\nGenerate one reply.' }
    ]
  });
  const data = await new Promise((resolve, reject) => {
    const req = https.request({
      hostname: 'api.groq.com',
      path: '/openai/v1/chat/completions',
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + key,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    }, (res) => {
      let body = '';
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => {
        try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
      });
    });
    req.on('error', reject);
    req.write(postData);
    req.end();
  });
  it.json.replyText = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
}
return items.map((i) => ({ json: i.json }));

const items = $input.all().map((i) => i.json);
if (items.length === 0) return [];
const { cookies } = items[0];
await $page.setCookie(...cookies);
const out = [];
for (const { url, replyText, id } of items) {
  try {
    await $page.goto(url, { waitUntil: 'networkidle2' });
    await $page.waitForSelector('div[data-testid="reply"]', { visible: true });
    await $page.click('div[data-testid="reply"]');
    await $page.waitForSelector('div[data-testid="tweetTextarea_0"], div[role="textbox"]', { visible: true });
    await $page.type('div[data-testid="tweetTextarea_0"], div[role="textbox"]', replyText, { delay: 50 });
    await $page.waitForSelector('div[data-testid="tweetButtonInline"], div[data-testid="tweetButton"]', { visible: true });
    await $page.click('div[data-testid="tweetButtonInline"], div[data-testid="tweetButton"]');
    out.push({ json: { id, url, replyText, posted: true } });
  } catch (e) {
    out.push({ json: { id, url, replyText, posted: false, error: String(e && e.message) } });
  }
  await new Promise((r) => setTimeout(r, 10000 + Math.random() * 20000));
}
return out;

const fs = require('fs');
const items = $input.all();
const n = items.length;
if (n === 0) return [];
const countPath = '/data/replyCount.json';
let countData = { count: 0 };
try {
  countData = JSON.parse(fs.readFileSync(countPath, 'utf8'));
} catch (e) {}
countData.count += n;
fs.writeFileSync(countPath, JSON.stringify(countData, null, 2));
const idsPath = '/data/repliedIds.json';
let ids = [];
try {
  ids = JSON.parse(fs.readFileSync(idsPath, 'utf8'));
} catch (e) {}
const postedIds = items.filter((i) => i.json.posted !== false).map((i) => i.json.id).filter(Boolean);
ids.push(...postedIds);
fs.writeFileSync(idsPath, JSON.stringify(ids, null, 2));
return items;
